import Foundation

/// A LAN-only companion. The native editor remains the project authority;
/// this client never receives host paths, executes plugins, or saves a copy.
enum ShareCompanion {
    static func html(csrfToken: String) -> String {
        #"""
        <!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>NetVista · Local collaboration</title>
        <style>
        :root{color-scheme:dark;--bg:#151719;--panel:#202326;--line:#393e43;--text:#eceff2;--muted:#a7afb7;--accent:#6bb5ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,input,select{font:inherit;color:inherit}button,select,input[type=number],input[type=text]{background:#30353a;border:1px solid #4b535b;border-radius:5px;padding:9px}button{cursor:pointer}button:hover{background:#424950}button:disabled,input:disabled{opacity:.45;cursor:default}button.primary{background:#2178be;border-color:#438ed0}header{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px 22px;border-bottom:1px solid var(--line)}header strong{font-size:18px}header small{color:var(--muted)}#connection{color:#80cba3}.bar{display:flex;gap:8px;align-items:center;padding:12px 22px;border-bottom:1px solid var(--line);flex-wrap:wrap}.bar button[aria-pressed=true]{border-color:var(--accent);color:var(--accent)}#project{margin-right:auto;font-size:16px}main{display:grid;grid-template-columns:220px minmax(240px,1fr) 300px;min-height:70vh}.panel{background:var(--panel);padding:18px;border-right:1px solid var(--line);min-width:0}h2{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em;margin:0 0 14px}.items{display:flex;flex-direction:column;gap:6px}.items button{text-align:left;overflow-wrap:anywhere}.items button.selected{border-color:var(--accent);background:#2a4055}.viewer{min-width:0;display:flex;flex-direction:column;padding:18px;gap:12px}.screen{background:#08090a;aspect-ratio:16/9;display:grid;place-items:center;overflow:hidden;border:1px solid #353b40;border-radius:5px}.screen img{width:100%;height:100%;object-fit:contain;grid-area:1/1}.screen span{grid-area:1/1;padding:20px;text-align:center;color:var(--muted)}.preview-tools{display:flex;align-items:center;gap:10px}.preview-tools input{flex:1;min-width:0}#previewTime{font-variant-numeric:tabular-nums;white-space:nowrap}.control{margin:0 0 18px}.control label{display:flex;justify-content:space-between;gap:12px;margin-bottom:6px}.control input[type=range]{width:100%;accent-color:var(--accent)}.axes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}.axes label{display:block;font-size:11px;color:var(--muted)}.axes input{width:100%;margin-top:5px}.muted{color:var(--muted);line-height:1.6;font-size:12px}#notice{margin:0;padding:12px 22px;background:#283441;min-height:42px;line-height:1.4}#notice.error{background:#502d2d}.row{display:flex;gap:8px;flex-wrap:wrap}.status{border-top:1px solid var(--line);padding:15px 22px;display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}.role{font-size:12px;color:#98c5ef}.empty{color:var(--muted);padding:12px 0}#sceneSelect{width:100%;margin-bottom:12px}.review{max-height:50vh;overflow:auto}#join{margin-bottom:18px;width:100%}.hide{display:none!important}a{color:var(--accent)}@media(max-width:1000px){main{grid-template-columns:180px minmax(180px,1fr) 260px}.panel,.viewer{padding:12px}}@media(max-width:720px){header{padding:14px}main{grid-template-columns:1fr}.items{flex-direction:row;overflow:auto}.items button{min-width:140px}.panel{border-bottom:1px solid var(--line)}.viewer{order:-1}.screen{max-height:45vh}.bar{padding:12px}#project{width:100%}header small{display:none}}
        </style></head><body>
        <header><div><strong>NetVista <small>STUDIO</small></strong><br><small>Local collaboration · native host</small></div><span id="connection">Connecting…</span></header>
        <div class="bar"><strong id="project">Shared project</strong><button data-mode="colour" aria-pressed="true">Colour</button><button data-mode="scene" aria-pressed="false">3D Scene</button><button data-mode="review" aria-pressed="false">Review</button></div>
        <p id="notice" role="status" aria-live="polite">Connecting to the Mac…</p>
        <main><aside class="panel"><h2 id="listHeading">Timeline video clips</h2><select id="sceneSelect" aria-label="Scene" class="hide"></select><div id="items" class="items"></div></aside>
        <section class="viewer"><div class="screen"><img id="preview" alt="Rendered preview from the host" class="hide"><span id="previewMessage">Select a clip or scene. Preview uses the host’s renderer.</span></div><div class="preview-tools"><button id="play" aria-label="Play preview">Play</button><input id="time" aria-label="Preview time" type="range" min="0" max="1" step="0.1" value="0"><output id="previewTime">0.0s</output></div><div class="muted">Preview time is private to this device. It does not move the Mac’s playhead. This is a sampled preview, not full-frame-rate playback.</div><div id="review" class="review hide"></div></section>
        <aside class="panel"><h2 id="settingsHeading">Primary grade</h2><button id="join" class="primary">Take Colour editing slot</button><div id="controls"></div><div class="row"><button id="apply" class="primary">Apply changes</button><button id="revert">Reload saved</button></div><div id="primitive" class="hide"><hr><p class="muted">Add a primitive to the selected scene.</p><div class="row"><select id="kind" aria-label="Primitive"><option value="cube">Cube</option><option value="sphere">Sphere</option><option value="cylinder">Cylinder</option><option value="plane">Plane</option></select><button id="add">Add</button><button id="delete">Delete object</button></div></div><p class="muted" id="limits">Primary grade controls preserve the Mac’s curves, nodes, LUTs and effects. Animated properties or unsaved host drafts remain protected.</p></aside></main>
        <div class="status"><div><span class="role" id="team">No active collaborators</span><br><span class="muted">Changes live in the host project. Save your work on the Mac to keep them.</span></div><div class="row"><input id="deviceName" type="text" maxlength="60" aria-label="Your device name" placeholder="Your device name"><button id="release">Release editing slot</button><a href="/manifest">Share summary</a></div></div>
        <script>
        'use strict';
        const csrf="\#(csrfToken)", $=id=>document.getElementById(id);
        let state=null,mode='colour',clipID=null,sceneID=null,objectID=null,sessionID=null,sessionDomain=null,dirty=false,pending=null,saving=false,serial=Promise.resolve(),polling=false,playing=false,previewBusy=false,previewURL=null,previewStamp='',draftRevision=null,online=false;
        const grade=[['exposure','Exposure',-3,3,.01],['contrast','Contrast',.25,2,.01],['saturation','Saturation',0,2,.01],['temperature','Temperature',2000,10000,10],['tint','Tint',-100,100,1],['vibrance','Vibrance',-1,1,.01]];
        function uuid(){return '10000000-1000-4000-8000-100000000000'.replace(/[018]/g,c=>(+c ^ (Math.random()*16 >> +c/4)).toString(16));}
        function notice(message,error=false){$('notice').textContent=message;$('notice').classList.toggle('error',error);}
        async function request(path,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000);try{const response=await fetch(path,{credentials:'same-origin',cache:'no-store',...options,signal:controller.signal});if(response.status===401){stopPlayback();sessionID=null;notice('Device access expired or was revoked. Reload this page to pair again.',true);}if(!response.ok)throw new Error(await response.text());online=true;$('connection').textContent='● Connected';return response;}finally{clearTimeout(timer);}}
        function send(command){if(command.kind!=='join')delete command.domain;const task=serial.then(async()=>{const response=await request('/api/command',{method:'POST',headers:{'Content-Type':'application/json','X-NetVista-CSRF':csrf,'X-NetVista-Device':($('deviceName').value||'Companion').replace(/[^\x20-\x7e]/g,'')},body:JSON.stringify({id:uuid(),projectID:state?.projectID,...command})});const result=await response.json();if(result.status!=='ok'){notice(result.message,true);if(['unavailable','unauthorized'].includes(result.status)){sessionID=null;sessionDomain=null;}}if(result.snapshot)accept(result.snapshot);return result;});serial=task.catch(()=>{});return task;}
        function selected(){if(mode==='colour')return state?.clips.find(c=>c.id===clipID);return state?.scenes.find(s=>s.id===sceneID)?.objects.find(o=>o.id===objectID);}
        function currentScene(){return state?.scenes.find(s=>s.id===sceneID);}
        function canEdit(){return online&&sessionID&&sessionDomain===mode&&selected()?.editable!==false;}
        function accept(next){state=next;$('project').textContent=next.title||'Shared project';if(sessionID&&!next.sessions.some(s=>s.id===sessionID)){sessionID=null;sessionDomain=null;}if(!next.clips.some(c=>c.id===clipID))clipID=next.clips[0]?.id||null;if(!next.scenes.some(s=>s.id===sceneID))sceneID=next.scenes[0]?.id||null;if(!currentScene()?.objects.some(o=>o.id===objectID))objectID=currentScene()?.objects[0]?.id||null;renderLists();if(!dirty&&!saving)renderControls();updatePermissions();$('team').textContent=next.sessions.map(s=>s.deviceName+' · '+(s.domain==='scene'?'3D':'Colour')).join(' / ')||'No active collaborators';refreshPreview();}
        function button(text,selectedValue,action){const b=document.createElement('button');b.textContent=text;b.classList.toggle('selected',selectedValue);b.onclick=action;return b;}
        function choose(kind,id){if(dirty&&!confirm('Discard your uncommitted changes?'))return;dirty=false;pending=null;draftRevision=null;stopPlayback();if(kind==='clip')clipID=id;else objectID=id;renderLists();renderControls();updatePermissions();$('time').value=0;previewStamp='';refreshPreview();}
        function renderLists(){const items=$('items');items.replaceChildren();$('sceneSelect').classList.toggle('hide',mode!=='scene');$('listHeading').textContent=mode==='colour'?'Timeline video clips':mode==='scene'?'Scene objects':'Project overview';if(mode==='colour')state.clips.forEach(c=>items.append(button(c.name,c.id===clipID,()=>choose('clip',c.id))));if(mode==='scene'){const select=$('sceneSelect');select.replaceChildren();state.scenes.forEach(s=>{const o=document.createElement('option');o.value=s.id;o.textContent=s.name;select.append(o);});select.value=sceneID||'';currentScene()?.objects.forEach(o=>items.append(button(o.name+' · '+o.kind,o.id===objectID,()=>choose('object',o.id))));}if(!items.children.length){const p=document.createElement('p');p.className='empty';p.textContent=mode==='colour'?'Add a video to the timeline on the Mac.':mode==='scene'?'Create a saved 3D scene on the Mac, or add an object below.':'Review shares clips and saved scene data.';items.append(p);}if(mode==='review'){const r=$('review');r.replaceChildren();state.clips.forEach(c=>{const p=document.createElement('p');p.textContent=c.name+' · grade revision '+c.revision;r.append(p);});state.scenes.forEach(s=>{const p=document.createElement('p');p.textContent=s.name+' · '+s.objects.length+' objects';r.append(p);});}}
        function renderControls(){const controls=$('controls');controls.replaceChildren();const item=selected();draftRevision=item?.revision??null;if(mode==='colour'&&item)grade.forEach(([key,label,min,max,step])=>{const row=document.createElement('div');row.className='control';const l=document.createElement('label'),out=document.createElement('output');l.textContent=label;out.id='value-'+key;out.textContent=Number(item.values[key]).toFixed(key==='temperature'?0:2);l.append(out);const input=document.createElement('input');input.type='range';input.id='field-'+key;input.min=min;input.max=max;input.step=step;input.value=item.values[key];input.oninput=()=>{dirty=true;out.textContent=Number(input.value).toFixed(key==='temperature'?0:2);notice('Adjusting grade — release the slider or press Apply changes.');};input.onchange=commit;row.append(l,input);controls.append(row);});if(mode==='scene'&&item)['position','rotation','scale'].forEach(group=>{const row=document.createElement('div');row.className='control';const heading=document.createElement('label');heading.textContent=group==='rotation'?'Rotation (degrees)':group==='position'?'Position':'Scale';const axes=document.createElement('div');axes.className='axes';['x','y','z'].forEach(axis=>{const label=document.createElement('label');label.textContent=axis.toUpperCase();const input=document.createElement('input');input.type='number';input.id='field-'+group+'-'+axis;input.step=group==='rotation'?1:.05;input.min=group==='scale'?.001:-10000;input.max=group==='scale'?1000:10000;input.value=item.transform[group][axis];input.oninput=()=>dirty=true;input.onchange=commit;label.append(input);axes.append(label);});row.append(heading,axes);controls.append(row);});const duration=mode==='scene'?currentScene()?.duration:selected()?.duration;$('time').max=Math.max(.1,duration||1);$('settingsHeading').textContent=mode==='colour'?'Primary grade':mode==='scene'?'Object transform':'Review';$('primitive').classList.toggle('hide',mode!=='scene');$('review').classList.toggle('hide',mode!=='review');$('limits').textContent=mode==='colour'?'Primary grade preserves the host’s curves, nodes, LUTs and effects. Host drafts and animated grade properties are protected.':'Build with primitives and move existing models. Rigging, sculpting, mesh editing and model import still use the native 3D editor.';}
        function updatePermissions(){document.querySelectorAll('#controls input').forEach(i=>{i.disabled=!canEdit();i.setAttribute('aria-label',i.id.replace('field-','').replaceAll('-',' '));});$('apply').disabled=!canEdit()||!selected();$('delete').disabled=!canEdit()||!selected();$('add').disabled=!(online&&sessionID&&sessionDomain==='scene'&&currentScene()?.editable!==false&&currentScene());$('join').disabled=mode==='review'||!!sessionID;$('join').textContent=sessionID?'Editing '+(sessionDomain==='scene'?'3D':'Colour'):'Take '+(mode==='scene'?'3D':'Colour')+' editing slot';$('release').disabled=!sessionID;}
        function values(){if(mode==='colour'){const result={};grade.forEach(([key])=>result[key]=Number($('field-'+key).value));return {colour:result};}const transform={};['position','rotation','scale'].forEach(g=>{transform[g]={};['x','y','z'].forEach(a=>transform[g][a]=Number($('field-'+g+'-'+a).value));});return {transform};}
        function commit(){if(!canEdit()||!selected())return;pending={kind:mode==='colour'?'colour':'transform',domain:mode,targetID:selected().id,sceneID:mode==='scene'?sceneID:undefined,expectedRevision:draftRevision,...values()};flush();}
        async function flush(){if(saving||!pending)return;const change=pending;pending=null;saving=true;notice('Applying to the host…');try{const result=await send({...change,sessionID});if(result.status==='ok'){const saved=mode==='colour'?result.snapshot.clips.find(c=>c.id===change.targetID):result.snapshot.scenes.find(s=>s.id===change.sceneID)?.objects.find(o=>o.id===change.targetID);draftRevision=saved?.revision??null;if(pending&&pending.targetID===change.targetID)pending.expectedRevision=draftRevision;notice('Applied to the shared project. Save on the Mac to keep your work.');previewStamp='';}else{pending=null;dirty=false;}}catch(error){pending=null;dirty=false;offline(error);}finally{saving=false;if(pending)flush();else{dirty=false;renderControls();updatePermissions();refreshPreview();}}}
        function offline(error){online=false;$('connection').textContent='Disconnected';updatePermissions();notice('Connection lost. Keep Share running on the Mac. '+error.message,true);}
        async function poll(){if(polling||saving||!document.hasFocus()&&document.hidden)return;polling=true;try{accept(await (await request('/api/project')).json());}catch(error){offline(error);}finally{polling=false;}}
        async function release(){if(!sessionID)return;await send({kind:'leave',sessionID});sessionID=null;sessionDomain=null;updatePermissions();}
        $('join').onclick=async()=>{try{const result=await send({kind:'join',domain:mode});if(result.status==='ok'){sessionID=result.sessionID;sessionDomain=mode;dirty=false;renderControls();updatePermissions();notice('You have the '+(mode==='scene'?'3D':'Colour')+' editing slot.');}}catch(error){offline(error);}};
        $('release').onclick=()=>release().catch(offline);$('apply').onclick=commit;$('revert').onclick=()=>{dirty=false;pending=null;renderControls();notice('Reloaded the host’s saved values.');};
        document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=async()=>{if(saving)return notice('Wait for your change to finish.');if(dirty&&!confirm('Discard uncommitted changes?'))return;try{await release();}catch(error){offline(error);return;}dirty=false;pending=null;mode=b.dataset.mode;stopPlayback();document.querySelectorAll('[data-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderLists();renderControls();updatePermissions();$('time').value=0;previewStamp='';refreshPreview();});
        $('sceneSelect').onchange=()=>{dirty=false;pending=null;sceneID=$('sceneSelect').value;objectID=currentScene()?.objects[0]?.id||null;stopPlayback();renderLists();renderControls();updatePermissions();$('time').value=0;previewStamp='';refreshPreview();};
        $('add').onclick=async()=>{try{const scene=currentScene();const result=await send({kind:'addObject',sessionID,domain:'scene',sceneID:scene.id,targetID:uuid(),objectKind:$('kind').value,expectedRevision:scene.revision});if(result.status==='ok')notice('Object added to the host scene.');}catch(error){offline(error);}};
        $('delete').onclick=async()=>{const item=selected();if(!item||!confirm('Delete '+item.name+' from the shared scene?'))return;try{const result=await send({kind:'deleteObject',sessionID,domain:'scene',sceneID,targetID:item.id,expectedRevision:item.revision});if(result.status==='ok')notice('Object deleted. Native scene Undo can restore it.');}catch(error){offline(error);}};
        $('time').oninput=()=>{$('previewTime').textContent=Number($('time').value).toFixed(1)+'s';refreshPreview();};
        function stopPlayback(){playing=false;$('play').textContent='Play';}
        $('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'Pause':'Play';};
        async function refreshPreview(){if(previewBusy||!online||mode==='review')return;const target=mode==='colour'?clipID:sceneID;if(!target)return;$('previewTime').textContent=Number($('time').value).toFixed(1)+'s';const revision=mode==='colour'?selected()?.revision:JSON.stringify(currentScene());const stamp=mode+target+$('time').value+revision;if(stamp===previewStamp)return;previewBusy=true;const capturedMode=mode,capturedTarget=target;try{const response=await request('/preview.jpg?kind='+(mode==='colour'?'clip':'scene')+'&id='+encodeURIComponent(target)+'&time='+encodeURIComponent($('time').value));const blob=await response.blob();if(mode!==capturedMode||(mode==='colour'?clipID:sceneID)!==capturedTarget)return;if(previewURL)URL.revokeObjectURL(previewURL);previewURL=URL.createObjectURL(blob);$('preview').src=previewURL;$('preview').classList.remove('hide');$('previewMessage').classList.add('hide');previewStamp=stamp;}catch(error){$('preview').classList.add('hide');$('previewMessage').classList.remove('hide');$('previewMessage').textContent='Preview unavailable. Check source files and saved scene on the Mac.';}finally{previewBusy=false;}}
        $('deviceName').value=/iPad|iPhone/.test(navigator.userAgent)?'iPad / iPhone':'Laptop companion';
        setInterval(poll,1000);setInterval(()=>{if(sessionID)send({kind:'heartbeat',sessionID}).catch(offline);},5000);setInterval(()=>{if(playing&&!previewBusy&&online){const next=Number($('time').value)+.5;if(next>Number($('time').max)){stopPlayback();return;}$('time').value=next;refreshPreview();}},500);poll();
        window.addEventListener('pagehide',()=>{stopPlayback();if(previewURL)URL.revokeObjectURL(previewURL);});
        </script></body></html>
        """#
    }
}
